function initScrollAnim(){const observerOptions={root:null,rootMargin:"0px",threshold:0.15};const observer=new IntersectionObserver((entries,observer)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');}else{entry.target.classList.remove('is-visible');}});},observerOptions);const animatedElements=document.querySelectorAll('.reveal-up, .reveal-left, .reveal-right, .reveal-scale, .reveal-stagger');animatedElements.forEach(el=>observer.observe(el));const staggerContainers=document.querySelectorAll('.reveal-stagger');staggerContainers.forEach(container=>{const children=container.children;Array.from(children).forEach((child,index)=>{child.style.transitionDelay=`${index * 50}ms`;child.classList.add('reveal-stagger-child');});});}
if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",initScrollAnim);}else{initScrollAnim();};